import{H as e,V as t,et as n,j as r}from"./chunks/framework.DSSJFrgb.js";var i=JSON.parse(`{"title":"About Mac PoTi","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}`),a={name:`about.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="about-mac-poti" tabindex="-1">About Mac PoTi <a class="header-anchor" href="#about-mac-poti" aria-label="Permalink to “About Mac PoTi”">​</a></h1><p>このページをつくった人は物覚えが悪いもので、たびたびMac Commandとググっていたときに、ある日突然スポンサー広告でMacBookに貼る 「ショートカットキー」ステッカーなるものが画像でずらりと並んでいました。</p><p>通販を見に行って何と便利そうな！と思ってすぐ真似することにした。</p><p>文章や説明はいらない、（なんだっけ）と思い出したいときに見る、知っているけど忘れがちなものを、シート化しました。</p><p>過去には、IllustratorやPhotoshopで作成されたであろう美しいショートカット表などをダウンロードさせてもらっていたけど・・・</p><p>「母さん、僕のあの帽子、いや壁紙になっているチートシート、どうしたんでせうね？」</p><div style="margin-top:4em;"></div><hr> というわけで、失くさない場所（Web+Github）におく。 <p>忘れるのはとにかくiTermで打ちたい Command ：touch　（なんだよ、タッチって）などなど</p><p>見るより、クリップボードコピーしたいので、自分の得意なHTMLでサクッとつくるのではなく、VitePressを使うことにしました。</p><p>ソースは右上のGithubアイコンをポチッと踏んでリポジトリにいけます。</p><div style="margin-top:2em;"></div><hr><h3 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to “内容”">​</a></h3><p>Markdownファイルを作成するときに、Mac Shortcut and Command Cheat Sheet なんて書いてられなかったため、<strong>なんとなくmac-poti.md</strong> とした。</p><p>それだけの命名で厳めしいプロジェクト名とかじゃないす。</p><p>（あら、便利そうね）とか（簡単そうね）と自己流にカスタムして使ってくださる方がいたら、幸いです。</p><div style="margin-top:2em;"></div><hr><p>ショートカットの記載内容は、商品化されているものを、ほぼパクリました。<br> デスクトップ派なので＋電源　などは使ったことないです。が、汎用性をとりました。<br></p><p>また普段検索で見ているサイトやページを引用させていただいた Command部分は末尾にURLをリンクしました。</p><div style="margin-top:2em;"></div><hr><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to “VitePress”">​</a></h3><p>ドキュメントに強い VitePress を1枚ペラで使う、しかもフル幅で、サイドバーやインページリンクも削る、というイレギュラーな使い方をしたので、その記録も同時に残すことにしました。</p><p>Mac PoTi とは関係なく、VitePress の frontmatter 参考にもなれば。</p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};